/**
 * What a new project's first commit holds (the coordinator's `InitialCommitProvider`):
 *
 * - from a template: every file of `templates/<id>/` (bundled into the Worker by
 *   scripts/bundle-templates.ts) with `{{projectName}}`, `{{host}}`, `{{mcpUrl}}` and `{{repoId}}`
 *   rendered, then `.platform/ci.ts`, `.platform/policy.ts` and AGENTS.md generated by
 *   @app/conventions for this project on top;
 * - an empty project: a short README, AGENTS.md and the default `.platform/*` files.
 *
 * The policy value is returned too: it is exactly what the generated `.platform/policy.ts`
 * exports (`defaultPolicyValue`), so the coordinator caches it for the initial commit and the
 * bootstrap Change needs no policy sandbox job.
 */

import {
  AGENTS_MD_PATH,
  agentsMd,
  call,
  DEFAULT_TEMPLATE,
  defaultCiTs,
  defaultPolicyTs,
  defaultPolicyValue,
  isTemplateId,
  type PlaceholderValues,
  projectSlug,
  renderPlaceholders,
  TEMPLATE_IDS,
  TEMPLATES,
  type TemplateId,
  templateGeneratedFiles,
} from "@app/conventions";
import { CoordinatorError, type InitialCommit, type InitialCommitProvider } from "@app/coordinator";
import { TEMPLATE_DIGESTS, TEMPLATE_FILES } from "../generated/templates.js";

export interface ProjectUrls {
  /** The platform origin agents use (no trailing slash). */
  host: string;
  mcpUrl: string;
}

export function unknownTemplate(template: string): CoordinatorError {
  return new CoordinatorError("invalid-input", `unknown template "${template}"`, {
    explanation: `Templates: ${TEMPLATE_IDS.join(", ")}. Omit template (and from) for an empty project.`,
    call: call("create_project", { template: DEFAULT_TEMPLATE }),
  });
}

/** The template's own files with placeholders rendered, plus the generated files on top. */
export function templateFiles(
  id: TemplateId,
  values: PlaceholderValues & { claimed: boolean },
): Record<string, string> {
  const source = TEMPLATE_FILES[id];
  if (source === undefined) throw unknownTemplate(id);
  const files: Record<string, string> = {};
  for (const [path, text] of Object.entries(source)) files[path] = renderPlaceholders(text, values);
  return { ...files, ...templateGeneratedFiles(id, values) };
}

/** README, AGENTS.md and default `.platform/*` for a project without a template. */
export function emptyProjectFiles(
  values: PlaceholderValues & { claimed: boolean },
  description: string | null,
): Record<string, string> {
  const ci = defaultCiTs({
    hasPackageJson: false,
    packageManager: "pnpm",
    lockfile: null,
    scripts: { lint: null, typecheck: null, test: null, build: null },
    typescript: false,
    testRunner: null,
    worker: false,
    cacheInputs: null,
  });
  const policy = defaultPolicyTs();
  const readme = [
    `# ${values.projectName}`,
    "",
    ...(description === null ? [] : [description, ""]),
    `A gittifacts project. Read AGENTS.md before changing anything: work starts from a Plan, lands`,
    "through a Change, and only the merge queue writes main.",
    "",
  ].join("\n");
  return {
    "README.md": readme,
    [AGENTS_MD_PATH]: agentsMd({
      projectName: values.projectName,
      host: values.host,
      mcpUrl: values.mcpUrl,
      repoId: values.repoId,
      claimed: values.claimed,
    }),
    [ci.path]: ci.text,
    [policy.path]: policy.text,
  };
}

export function initialCommitProvider(urls: ProjectUrls): InitialCommitProvider {
  return async (input): Promise<InitialCommit> => {
    const values = {
      projectName: projectSlug(input.name),
      host: urls.host,
      mcpUrl: urls.mcpUrl,
      repoId: input.repoId,
      claimed: input.claimed,
    };
    if (input.template === null) {
      return {
        files: emptyProjectFiles(values, input.description),
        message: "Initial commit\n\nCreated by gittifacts create_project (empty project).",
        policy: defaultPolicyValue(),
      };
    }
    if (!isTemplateId(input.template)) throw unknownTemplate(input.template);
    const id = input.template;
    return {
      files: templateFiles(id, values),
      message: `Initial commit from template ${id}\n\nCreated by gittifacts create_project (template digest ${TEMPLATE_DIGESTS[id]?.slice(0, 12) ?? "unknown"}).`,
      policy: defaultPolicyValue({ previewRoutes: TEMPLATES[id].previewRoutes }),
    };
  };
}
